pub fn updateRef(self: *PostgresSQLConnection) void {
        _ = self.updateHasPendingActivity();
        if ((self.pending_activity_count.raw > 0)) {
            _ = self.poll_ref.ref(self.vm);
        } else {
            _ = self.poll_ref.unref(self.vm);
        }
}

pub fn getConnected(self: *PostgresSQLConnection) JSValue {
        return JSValue.jsBoolean((self.status == Status.connected));
}

pub fn consumeOnConnectCallback(self: *const PostgresSQLConnection, globalObject: *jsc.JSGlobalObject) ?jsc.JSValue {
